Here is the commit message:
mm/memfd_luo: fix physical address conversion in put_folios
 cleanup

In memfd_luo_retrieve_folios()'s put_folios cleanup path:

1. kho_restore_folio() expects a phys_addr_t (physical address) but
   receives a raw PFN (pfolio->pfn). This causes kho_restore_page() to
   check the wrong physical address (pfn << PAGE_SHIFT instead of the
   actual physical address).

2. This loop lacks the !pfolio->pfn check that exists in the main
   retrieval loop and memfd_luo_discard_folios(), which could
   incorrectly process sparse file holes where pfn=0.

Fix by converting PFN to physical address with PFN_PHYS() and adding
the !pfolio->pfn check, matching the pattern used elsewhere in this file.

This issue was identified by the AI review.
https://sashiko.dev/#/patchset/20260323110747.193569-1-duanchenghao@kylinos.cn

Link: https://lore.kernel.org/20260326084727.118437-6-duanchenghao@kylinos.cn
Fixes: b3749f174d68 ("mm: memfd_luo: allow preserving memfd")
Signed-off-by: Chenghao Duan <duanchenghao@kylinos.cn>
Reviewed-by: Pasha Tatashin <pasha.tatashin@soleen.com>
Reviewed-by: Pratyush Yadav <pratyush@kernel.org>
Cc: Haoran Jiang <jianghaoran@kylinos.cn>
Cc: Mike Rapoport (Microsoft) <rppt@kernel.org>
Cc: <stable@vger.kernel.org>
Signed-off-by: Andrew Morton <akpm@linux-foundation.org>

Here is the root cause:
In the cleanup path of `memfd_luo_retrieve_folios()`, the `kho_restore_folio()` function is called with a raw PFN (`pfolio->pfn`) instead of the expected physical address (`phys_addr_t`), which leads to incorrect physical address translation (`pfn << PAGE_SHIFT` instead of actual physical address). Additionally, the loop lacks a check for `!pfolio->pfn` to skip sparse file holes (pfn=0), which exists in the main retrieval loop and `memfd_luo_discard_folios()`. This causes improper processing of holes and potential access to invalid physical addresses.

Here is the patch:

 static int memfd_luo_retrieve_folios(struct file *file,
 				     struct memfd_luo_folio_ser *folios_ser,
 				     u64 nr_folios)
 {
 	struct inode *inode = file_inode(file);
 	struct address_space *mapping = inode->i_mapping;
 	struct folio *folio;
 	long npages, nr_added_pages = 0;
 	int err = -EIO;
 	long i;

 	for (i = 0; i < nr_folios; i++) {
 		const struct memfd_luo_folio_ser *pfolio = &folios_ser[i];
 		phys_addr_t phys;
 		u64 index;
 		int flags;

 		if (!pfolio->pfn)
 			continue;

 		phys = PFN_PHYS(pfolio->pfn);
 		folio = kho_restore_folio(phys);
 		if (!folio) {
 			pr_err("Unable to restore folio at physical address: %llx\n",
 			       phys);
 			goto put_folios;
 		}
 		index = pfolio->index;
 		flags = pfolio->flags;

 		/* Set up the folio for insertion. */
 		__folio_set_locked(folio);
 		__folio_set_swapbacked(folio);

 		err = mem_cgroup_charge(folio, NULL, mapping_gfp_mask(mapping));
 		if (err) {
 			pr_err("shmem: failed to charge folio index %ld: %d\n",
 			       i, err);
 			goto unlock_folio;
 		}

 		err = shmem_add_to_page_cache(folio, mapping, index, NULL,
 					      mapping_gfp_mask(mapping));
 		if (err) {
 			pr_err("shmem: failed to add to page cache folio index %ld: %d\n",
 			       i, err);
 			goto unlock_folio;
 		}

 		if (flags & MEMFD_LUO_FOLIO_UPTODATE)
 			folio_mark_uptodate(folio);
 		if (flags & MEMFD_LUO_FOLIO_DIRTY)
 			folio_mark_dirty(folio);

 		npages = folio_nr_pages(folio);
 		err = shmem_inode_acct_blocks(inode, npages);
 		if (err) {
 			pr_err("shmem: failed to account folio index %ld(%ld pages): %d\n",
 			       i, npages, err);
 			goto unlock_folio;
 		}

 		nr_added_pages += npages;
 		folio_add_lru(folio);
 		folio_unlock(folio);
 		folio_put(folio);
 	}

 	shmem_recalc_inode(inode, nr_added_pages, 0);

 	return 0;

 unlock_folio:
 	folio_unlock(folio);
 	folio_put(folio);
 put_folios:
 	/*
 	 * Note: don't free the folios already added to the file. They will be
 	 * freed when the file is freed. Free the ones not added yet here.
 	 */
 	for (long j = i + 1; j < nr_folios; j++) {
 		const struct memfd_luo_folio_ser *pfolio = &folios_ser[j];
+		phys_addr_t phys;
+
+		if (!pfolio->pfn)
+			continue;

-		folio = kho_restore_folio(pfolio->pfn);
+		phys = PFN_PHYS(pfolio->pfn);
+		folio = kho_restore_folio(phys);
 		if (folio)
 			folio_put(folio);
 	}

 	shmem_recalc_inode(inode, nr_added_pages, 0);

 	return err;
 }



